func TestLessLE(t *testing.T) {
	t.Parallel()

	for _, test := range []struct {
		lhs, rhs []byte
		want     uint64
	}{
		{[]byte{1, 0}, []byte{2, 0}, 1},
		{[]byte{2, 0}, []byte{1, 0}, 0},
		{[]byte{2, 0}, []byte{2, 0}, 0},
		{[]byte{0xff, 0}, []byte{0, 1}, 1}, // the last byte is the most significant
		{[]byte{0, 1}, []byte{0xff, 0}, 0},
		{[]byte{0, 0xff}, []byte{0xff, 0xfe}, 0},
	} {
		if got := lessLE(test.lhs, test.rhs); got != test.want {
			t.Errorf("lessLE(%x, %x) = %d, want %d", test.lhs, test.rhs, got, test.want)
		}
	}
}

